SELECT
    id, name, ip_address as ipAddress, port, os_type as osType,
    cpu_cores as cpuCores, memory_mb as memoryMb, disk_gb as diskGb,
    status, connection_status as connectionStatus, ws_session_id as wsSessionId, last_heartbeat as lastHeartbeat,
    secret_id as secretId, secret_expire_time as secretExpireTime,
    system_info as systemInfo, capabilities, network_config as networkConfig, metadata,
    created_at as createdAt, updated_at as updatedAt, created_by as createdBy, updated_by as updatedBy
FROM vm_instances
WHERE 1=1

    AND status = #{status}


    AND os_type = #{osType}


    AND connection_status = #{connectionStatus}


    AND (name LIKE CONCAT('%', #{keyword}, '%') OR ip_address LIKE CONCAT('%', #{keyword}, '%'))



        ORDER BY ${sortField} ${sortOrder}


        ORDER BY created_at DESC


LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM vm_instances
WHERE 1=1

    AND status = #{status}


    AND os_type = #{osType}


    AND connection_status = #{connectionStatus}


    AND (name LIKE CONCAT('%', #{keyword}, '%') OR ip_address LIKE CONCAT('%', #{keyword}, '%'))

