UPDATE vm_instances SET
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}

        , name = #{name}


        , ip_address = #{ipAddress}


        , port = #{port}


        , os_type = #{osType}


        , cpu_cores = #{cpuCores}


        , memory_mb = #{memoryMb}


        , disk_gb = #{diskGb}


        , system_info = #{systemInfo}


        , capabilities = #{capabilities}


        , network_config = #{networkConfig}


        , metadata = #{metadata}

WHERE id = #{id}

